    return [...this.rows.values()].filter((row) => row.deletedAt == null).sort((a, b) => compareKeys(keyOf(a), keyOf(b)))
  }

  /** The row with this primary key, or null. */
  async findById(id: number): Promise<Product | null> {
    return this.visible().find((row) => row.id === id) ?? null
  }

  /** At most `limit` rows from `offset`, by primary key, and how many there are. */
  async list(offset: number = 0, limit: number = 50): Promise<Page<Product>> {
    const rows = this.visible()
    return { items: rows.slice(offset, offset + limit), total: rows.length, offset, limit }
  }

  /** Rows with this category_id, by primary key. */
  async listByCategoryId(categoryId: number): Promise<Product[]> {
    return this.visible().filter((row) => row.categoryId === categoryId)
  }

