  async findAllByStatus(status: string): Promise<Product[]> {
    return this.visible().filter((row) => row.status === status)
  }

  /** Stores a new row; the values the database fills are read back. */
  async insert(entity: Product): Promise<Product> {
    if (entity.id === undefined) entity.id = this.nextId++
    if (entity.version === undefined) entity.version = 1
    this.rows.set(JSON.stringify(keyOf(entity)), entity)
    return entity
  }

  /** Stores the changes made to a row read from this repository. */
  async update(entity: Product): Promise<Product> {
    this.rows.set(JSON.stringify(keyOf(entity)), entity)
    return entity
  }

  /** Removes a row read from this repository. */
  async delete(entity: Product): Promise<void> {
    this.rows.delete(JSON.stringify(keyOf(entity)))
  }
}

