/** Repository of the "tags" table: reads and writes rows, and decides nothing. */
import { Tag } from '../entities/tag.js'
import { ConflictError } from '../errors.js'
import { Prisma } from '../generated/prisma/client.js'
import type { Page } from '../paging.js'

/** Where tags rows are kept. Services depend only on this interface. */
export interface TagRepository {
  findById(id: number): Promise<Tag | null>
  list(offset?: number, limit?: number): Promise<Page<Tag>>
  insert(entity: Tag): Promise<Tag>
  update(entity: Tag): Promise<Tag>
  delete(entity: Tag): Promise<void>
}

/** The key of a row, as a list of its key values. */
function keyOf(row: Tag): unknown[] {
  return [row.id]
}

/** Orders two keys value by value. */
function compareKeys(a: unknown[], b: unknown[]): number {
  for (let index = 0; index < a.length; index++) {
    const x = a[index] as number | string
    const y = b[index] as number | string
    if (x < y) return -1
    if (x > y) return 1
  }
  return 0
}

/** The Tag of a row Prisma read. */
function toEntity(row: Prisma.TagModel): Tag {
  return Object.assign(new Tag(), {
    id: row.id,
    label: row.label,
  })
}

/** The values of a new row; those left undefined take the database's default. */
function createData(entity: Tag): Prisma.TagUncheckedCreateInput {
  return {
    id: entity.id,
    label: entity.label,
  }
}

/** The values a change writes: not the key, nor what the database fills. */
function updateData(entity: Tag): Prisma.TagUncheckedUpdateManyInput {
  return {
    label: entity.label,
  }
}

/** Keeps tags rows in the database, through a Prisma client. It never commits: the transaction belongs to the client it was given. */
export class SqlTagRepository implements TagRepository {
  constructor(private readonly db: Prisma.TransactionClient) {}

  /** The row with this primary key, or null. */
  async findById(id: number): Promise<Tag | null> {
    const row = await this.db.tag.findFirst({ where: { id } })
    return row === null ? null : toEntity(row)
  }

  /** At most `limit` rows from `offset`, by primary key, and how many there are. */
  async list(offset: number = 0, limit: number = 50): Promise<Page<Tag>> {
    const rows = await this.db.tag.findMany({ orderBy: { id: 'asc' }, skip: offset, take: limit })
    const total = await this.db.tag.count()
    return { items: rows.map(toEntity), total, offset, limit }
  }

  /** Stores a new row; the values the database fills are read back. */
  async insert(entity: Tag): Promise<Tag> {
    try {
      return Object.assign(entity, toEntity(await this.db.tag.create({ data: createData(entity) })))
    } catch (error) {
      if (error instanceof Prisma.PrismaClientKnownRequestError) throw new ConflictError('Tag', `the database refused the change: ${error.message}`)
      throw error
    }
  }

  /** Stores the changes made to a row read from this repository. */
  async update(entity: Tag): Promise<Tag> {
    try {
      await this.db.tag.updateMany({ where: { id: entity.id }, data: updateData(entity) })
    } catch (error) {
      if (error instanceof Prisma.PrismaClientKnownRequestError) throw new ConflictError('Tag', `the database refused the change: ${error.message}`)
      throw error
    }
    return entity
  }

  /** Removes a row read from this repository. */
  async delete(entity: Tag): Promise<void> {
    try {
      await this.db.tag.deleteMany({ where: { id: entity.id } })
    } catch (error) {
      if (error instanceof Prisma.PrismaClientKnownRequestError) throw new ConflictError('Tag', `the database refused the change: ${error.message}`)
      throw error
    }
  }
}

