/** The repositories of every table, and the transaction of each service operation. Each service operation runs in `transaction()`: committed when it ends, rolled back when it fails. */
import type { Prisma, PrismaClient } from './generated/prisma/client.js'
import { MemoryAuditLogRepository, SqlAuditLogRepository, type AuditLogRepository } from './repositories/audit-log.js'
import { MemoryCategoryRepository, SqlCategoryRepository, type CategoryRepository } from './repositories/category.js'
import { MemoryCustomerRepository, SqlCustomerRepository, type CustomerRepository } from './repositories/customer.js'
import { MemoryOrderRepository, SqlOrderRepository, type OrderRepository } from './repositories/order.js'
import { MemoryOrderLineRepository, SqlOrderLineRepository, type OrderLineRepository } from './repositories/order-line.js'
import { MemoryProductRepository, SqlProductRepository, type ProductRepository } from './repositories/product.js'
import { MemoryProductTagRepository, SqlProductTagRepository, type ProductTagRepository } from './repositories/product-tag.js'
import { MemoryTagRepository, SqlTagRepository, type TagRepository } from './repositories/tag.js'

/** What services depend on: a repository per table and a transaction. */
export interface UnitOfWork {
  readonly customers: CustomerRepository
  readonly categories: CategoryRepository
  readonly products: ProductRepository
  readonly orders: OrderRepository
  readonly orderLines: OrderLineRepository
  readonly tags: TagRepository
  readonly productTags: ProductTagRepository
  readonly auditLog: AuditLogRepository
  /** Runs `work` with the repositories of the transaction; commits when it ends, rolls back when it throws. */
  transaction<T>(work: (uow: UnitOfWork) => Promise<T>): Promise<T>
}

/** The repositories over one Prisma client: the application's, or the one of a transaction. */
export class SqlUnitOfWork implements UnitOfWork {
  readonly customers: CustomerRepository
  readonly categories: CategoryRepository
  readonly products: ProductRepository
  readonly orders: OrderRepository
  readonly orderLines: OrderLineRepository
  readonly tags: TagRepository
  readonly productTags: ProductTagRepository
  readonly auditLog: AuditLogRepository

  constructor(
    readonly db: Prisma.TransactionClient,
    private readonly inTransaction = false,
  ) {
    this.customers = new SqlCustomerRepository(db)
    this.categories = new SqlCategoryRepository(db)
    this.products = new SqlProductRepository(db)
    this.orders = new SqlOrderRepository(db)
    this.orderLines = new SqlOrderLineRepository(db)
    this.tags = new SqlTagRepository(db)
    this.productTags = new SqlProductTagRepository(db)
    this.auditLog = new SqlAuditLogRepository(db)
  }

  /** Runs `work` in a transaction of its own, or in the one already open. */
  transaction<T>(work: (uow: UnitOfWork) => Promise<T>): Promise<T> {
    if (this.inTransaction) return work(this)
    return (this.db as PrismaClient).$transaction((db) => work(new SqlUnitOfWork(db, true)))
  }
}

/** The in-memory repositories, for tests and for trying the services without a database. */
export class MemoryUnitOfWork implements UnitOfWork {
  readonly customers = new MemoryCustomerRepository()
  readonly categories = new MemoryCategoryRepository()
  readonly products = new MemoryProductRepository()
  readonly orders = new MemoryOrderRepository()
  readonly orderLines = new MemoryOrderLineRepository()
  readonly tags = new MemoryTagRepository()
  readonly productTags = new MemoryProductTagRepository()
  readonly auditLog = new MemoryAuditLogRepository()

  /** Memory has no transactions: changes are kept as they are made. */
  transaction<T>(work: (uow: UnitOfWork) => Promise<T>): Promise<T> {
    return work(this)
  }
}

