/** Tests of the "tags" table. */
import { describe, expect, it } from 'vitest'
import { useTestDatabase } from './database.js'
import { addTag } from './factories.js'

/** The repositories over the test database, opened empty for every test */
const sqlUow = useTestDatabase()

describe('tags repository', () => {
  it('is stored and read back', async () => {
    const uow = sqlUow()
    const stored = await addTag(uow, 1)
    const found = await uow.tags.findById(stored.id)
    expect(found).not.toBeNull()
    expect(found!.id).toEqual(stored.id)
  })

  it('lists rows by key', async () => {
    const uow = sqlUow()
    await addTag(uow, 1)
    await addTag(uow, 2)
    const page = await uow.tags.list(0, 1)
    expect(page.total).toBe(2)
    expect(page.items).toHaveLength(1)
  })

  it('stores the changes', async () => {
    const uow = sqlUow()
    const stored = await addTag(uow, 1)
    stored.label = 'changed'
    await uow.tags.update(stored)
    const found = await uow.tags.findById(stored.id)
    expect(found?.label).toBe('changed')
  })

  it('is deleted', async () => {
    const uow = sqlUow()
    const stored = await addTag(uow, 1)
    await uow.tags.delete(stored)
    expect(await uow.tags.findById(stored.id)).toBeNull()
  })
})

